import datetime

def parse_rows(text):
    lines = text.strip().split('\n')
    headers = lines[0].split('\t')
    parsed_rows = []

    for line in lines[1:]:
        values = line.split('\t')
        row = {}
        for header, value in zip(headers, values):
            if header == 'qty_g':
                row[header] = int(value.replace(',', ''))
            elif header == 'harvested':
                row[header] = datetime.datetime.strptime(value, '%Y-%m-%d').date()
            else:
                row[header] = value
        parsed_rows.append(row)

    return parsed_rows
