def assign(script_ids, graders):
    def fair_share(scripts, num_graders):
        return max(1, len(scripts) // num_graders)

    num_graders = len(graders)
    max_assignments = fair_share(script_ids, num_graders) * 1.5
    assignments = {grader: [] for grader in graders}
    grader_index = 0
    grader_count = 0

