        rates = defaultdict(lambda: {'passed': 0, 'enrolled': 0})
        for section, method, passed, enrolled in rows:
            rates[section][method] = rates[section][method] + (passed, enrolled)
        return rates

    rates = pass_rate(rows)
    section_totals = defaultdict(lambda: {'A': 0, 'B': 0})
    for section, method, passed, enrolled in rows:
        section_totals[section]['A'] += passed
        section_totals[section]['B'] += enrolled

    overall_A = overall_B = 0
    overall_sections = defaultdict(lambda: {'A': 0, 'B': 0})
    for section, method, passed, enrolled in rows:
        overall_A += passed
        overall_B += enrolled
        overall_sections[section][method] = overall_sections[section][method] + (passed, enrolled)

    for section in section_totals:
        if section_totals[section]['A'] / section_totals[section]['B'] > overall_A / overall_B:
            return "A"
        elif section_totals[section]['A'] / section_totals[section]['B'] < overall_A / overall_B:
            return "B"

    return "tie"
```

